 import React, { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import { ChevronLeft, Check, Globe, Languages, ChevronRight, Search } from 'lucide-react'

export default function Language() {
    const navigate = useNavigate()
    const [selectedLanguage, setSelectedLanguage] = useState(() => {
        return localStorage.getItem('language') || 'en'
    })
    const [searchQuery, setSearchQuery] = useState('')

    useEffect(() => {
        localStorage.setItem('language', selectedLanguage)
        // Here you would load the translation file
        // For now, we just save the preference
    }, [selectedLanguage])

    const languages = [
        // South African Languages
        { 
            id: 'zu', 
            name: 'isiZulu', 
            nativeName: 'isiZulu',
            code: 'zu',
            region: '🇿🇦',
            category: 'South African'
        },
        { 
            id: 'xh', 
            name: 'isiXhosa', 
            nativeName: 'isiXhosa',
            code: 'xh',
            region: '🇿🇦',
            category: 'South African'
        },
        { 
            id: 'af', 
            name: 'Afrikaans', 
            nativeName: 'Afrikaans',
            code: 'af',
            region: '🇿🇦',
            category: 'South African'
        },
        { 
            id: 'nso', 
            name: 'Sepedi', 
            nativeName: 'Sepedi',
            code: 'nso',
            region: '🇿🇦',
            category: 'South African'
        },
        { 
            id: 'tn', 
            name: 'Setswana', 
            nativeName: 'Setswana',
            code: 'tn',
            region: '🇿🇦',
            category: 'South African'
        },
        { 
            id: 'st', 
            name: 'Sesotho', 
            nativeName: 'Sesotho',
            code: 'st',
            region: '🇿🇦',
            category: 'South African'
        },
        { 
            id: 'ts', 
            name: 'Xitsonga', 
            nativeName: 'Xitsonga',
            code: 'ts',
            region: '🇿🇦',
            category: 'South African'
        },
        { 
            id: 'ss', 
            name: 'siSwati', 
            nativeName: 'siSwati',
            code: 'ss',
            region: '🇿🇦',
            category: 'South African'
        },
        { 
            id: 've', 
            name: 'Tshivenda', 
            nativeName: 'Tshivenda',
            code: 've',
            region: '🇿🇦',
            category: 'South African'
        },
        { 
            id: 'nr', 
            name: 'isiNdebele', 
            nativeName: 'isiNdebele',
            code: 'nr',
            region: '🇿🇦',
            category: 'South African'
        },
        // International Languages
        { 
            id: 'en', 
            name: 'English', 
            nativeName: 'English',
            code: 'en',
            region: '🇬🇧',
            category: 'International'
        },
        { 
            id: 'es', 
            name: 'Spanish', 
            nativeName: 'Español',
            code: 'es',
            region: '🇪🇸',
            category: 'International'
        },
        { 
            id: 'fr', 
            name: 'French', 
            nativeName: 'Français',
            code: 'fr',
            region: '🇫🇷',
            category: 'International'
        },
        { 
            id: 'de', 
            name: 'German', 
            nativeName: 'Deutsch',
            code: 'de',
            region: '🇩🇪',
            category: 'International'
        },
        { 
            id: 'pt', 
            name: 'Portuguese', 
            nativeName: 'Português',
            code: 'pt',
            region: '🇵🇹',
            category: 'International'
        }
    ]

    const filteredLanguages = languages.filter(lang => 
        lang.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        lang.nativeName.toLowerCase().includes(searchQuery.toLowerCase())
    )

    const saLanguages = filteredLanguages.filter(l => l.category === 'South African')
    const internationalLanguages = filteredLanguages.filter(l => l.category === 'International')

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-gray-900 px-4 py-6 pb-20 transition-colors duration-200">
            <div className="flex items-center gap-3 mb-6">
                <button 
                    onClick={() => navigate(-1)}
                    className="p-2 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-lg transition"
                >
                    <ChevronLeft size={24} className="text-gray-700 dark:text-gray-300" />
                </button>
                <h1 className="text-2xl font-bold text-gray-800 dark:text-white">Language</h1>
            </div>

            {/* Search Bar */}
            <div className="relative mb-6">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 dark:text-gray-500" size={18} />
                <input
                    type="text"
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    placeholder="Search languages..."
                    className="w-full px-4 py-2 pl-10 pr-4 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-gray-400 dark:focus:ring-gray-600 text-gray-800 dark:text-white transition-colors duration-200"
                />
            </div>

            {/* South African Languages Section */}
            {saLanguages.length > 0 && (
                <div className="mb-6">
                    <div className="flex items-center gap-2 mb-3">
                        <div className="w-1 h-6 bg-green-600 dark:bg-green-400 rounded-full"></div>
                        <h2 className="text-sm font-semibold text-gray-600 dark:text-gray-400 uppercase tracking-wider">
                            South African Languages 🇿🇦
                        </h2>
                    </div>
                    <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden transition-colors duration-200">
                        {saLanguages.map((lang, index) => {
                            const isSelected = selectedLanguage === lang.id
                            return (
                                <button
                                    key={lang.id}
                                    onClick={() => setSelectedLanguage(lang.id)}
                                    className={`w-full flex items-center justify-between px-4 py-4 hover:bg-gray-50 dark:hover:bg-gray-700 transition border-b border-gray-100 dark:border-gray-700 last:border-0 ${
                                        isSelected ? 'bg-green-50 dark:bg-green-900/20' : ''
                                    }`}
                                >
                                    <div className="flex items-center gap-3">
                                        <div className={`w-10 h-10 rounded-full flex items-center justify-center ${
                                            isSelected 
                                                ? 'bg-green-600 dark:bg-green-500 text-white' 
                                                : 'bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-400'
                                        }`}>
                                            <span className="text-lg">{lang.region}</span>
                                        </div>
                                        <div className="text-left">
                                            <span className="font-medium text-gray-800 dark:text-white">{lang.name}</span>
                                            <p className="text-xs text-gray-400 dark:text-gray-500">{lang.nativeName}</p>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        {isSelected && (
                                            <Check size={20} className="text-green-600 dark:text-green-400" />
                                        )}
                                        <ChevronRight size={18} className={`text-gray-300 dark:text-gray-600 ${isSelected ? 'opacity-50' : ''}`} />
                                    </div>
                                </button>
                            )
                        })}
                    </div>
                </div>
            )}

            {/* International Languages Section */}
            {internationalLanguages.length > 0 && (
                <div className="mb-6">
                    <div className="flex items-center gap-2 mb-3">
                        <div className="w-1 h-6 bg-blue-600 dark:bg-blue-400 rounded-full"></div>
                        <h2 className="text-sm font-semibold text-gray-600 dark:text-gray-400 uppercase tracking-wider">
                            International Languages 🌍
                        </h2>
                    </div>
                    <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden transition-colors duration-200">
                        {internationalLanguages.map((lang, index) => {
                            const isSelected = selectedLanguage === lang.id
                            return (
                                <button
                                    key={lang.id}
                                    onClick={() => setSelectedLanguage(lang.id)}
                                    className={`w-full flex items-center justify-between px-4 py-4 hover:bg-gray-50 dark:hover:bg-gray-700 transition border-b border-gray-100 dark:border-gray-700 last:border-0 ${
                                        isSelected ? 'bg-blue-50 dark:bg-blue-900/20' : ''
                                    }`}
                                >
                                    <div className="flex items-center gap-3">
                                        <div className={`w-10 h-10 rounded-full flex items-center justify-center ${
                                            isSelected 
                                                ? 'bg-blue-600 dark:bg-blue-500 text-white' 
                                                : 'bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-400'
                                        }`}>
                                            <span className="text-lg">{lang.region}</span>
                                        </div>
                                        <div className="text-left">
                                            <span className="font-medium text-gray-800 dark:text-white">{lang.name}</span>
                                            <p className="text-xs text-gray-400 dark:text-gray-500">{lang.nativeName}</p>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        {isSelected && (
                                            <Check size={20} className="text-blue-600 dark:text-blue-400" />
                                        )}
                                        <ChevronRight size={18} className={`text-gray-300 dark:text-gray-600 ${isSelected ? 'opacity-50' : ''}`} />
                                    </div>
                                </button>
                            )
                        })}
                    </div>
                </div>
            )}

            {filteredLanguages.length === 0 && (
                <div className="text-center py-12 bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
                    <Languages size={48} className="text-gray-300 dark:text-gray-600 mx-auto mb-4" />
                    <p className="text-gray-500 dark:text-gray-400">No languages found</p>
                    <p className="text-sm text-gray-400 dark:text-gray-500">Try a different search term</p>
                </div>
            )}

            <div className="mt-6 bg-yellow-50 dark:bg-yellow-900/30 rounded-xl p-4 border border-yellow-200 dark:border-yellow-800">
                <div className="flex items-start gap-3">
                    <Languages size={20} className="text-yellow-600 dark:text-yellow-400 mt-0.5" />
                    <div>
                        <p className="text-sm font-medium text-yellow-700 dark:text-yellow-300">
                            Language Support Status
                        </p>
                        <p className="text-sm text-yellow-600 dark:text-yellow-400">
                            🇿🇦 South African languages are ready to be implemented! 
                            {selectedLanguage === 'zu' && ' 🔥 Sawubona!'}
                            {selectedLanguage === 'xh' && ' 🔥 Molo!'}
                            {selectedLanguage === 'af' && ' 🔥 Hallo!'}
                            {selectedLanguage === 'nso' && ' 🔥 Thobela!'}
                            {selectedLanguage === 'tn' && ' 🔥 Dumela!'}
                            {selectedLanguage === 'st' && ' 🔥 Lumela!'}
                            {selectedLanguage === 'ts' && ' 🔥 Avuxeni!'}
                            {selectedLanguage === 'ss' && ' 🔥 Sawubona!'}
                            {selectedLanguage === 've' && ' 🔥 Ndi matsheloni!'}
                            {selectedLanguage === 'nr' && ' 🔥 Salibonani!'}
                        </p>
                    </div>
                </div>
            </div>
        </div>
    )
}
